#include "sda_expanded_search.h"
#include "sda_random_driver.h"
#include <string.h>
int main(void){mpfr_t lo,hi,x,last,pl,pu,slo,shi,a,b,c;mpfr_inits2(192,lo,hi,x,last,pl,pu,slo,shi,a,b,c,(mpfr_ptr)0);mpfr_set_d(lo,.1,MPFR_RNDN);mpfr_set_d(hi,.9,MPFR_RNDN);for(int mode=0;mode<2;mode++){mpfr_set_zero(last,0);for(unsigned i=0;i<10;i++){if(sda_epsilon_grid_point(x,lo,hi,i,10,(sda_epsilon_search_mode)mode)||mpfr_sgn(x)<=0||mpfr_cmp_ui(x,1)>=0||(i&&mpfr_cmp(x,last)<=0))return 1;mpfr_set(last,x,MPFR_RNDN);}}if(sda_expanded_stage_bounds(15,13,0,pl,pu,slo,shi)||mpfr_cmp(pl,slo)||mpfr_cmp(pu,shi))return 2;if(sda_expanded_stage_bounds(15,13,1,pl,pu,slo,shi))return 3;mpfr_mul_2ui(slo,slo,1,MPFR_RNDN);if(mpfr_cmp(slo,pl))return 4;sda_u128 p[3]={2,1,0},qv[3]={1,2,0},cc[3]={2,3,3};sda_frozen_reference f={3,3,{2,1,0},{2,3,3}};if(!sda_frozen_equal(3,3,p,cc,&f)||sda_frozen_equal(3,3,qv,cc,&f))return 5;mpfr_t al[2];mpfr_init2(al[0],192);mpfr_init2(al[1],192);mpfr_set_d(al[0],.4,MPFR_RNDN);mpfr_set_d(al[1],.6,MPFR_RNDN);char h1[17],h2[17],h3[17];sda_expanded_basis_hash(h1,al,2,lo,192);sda_expanded_basis_hash(h2,al,2,lo,192);sda_expanded_basis_hash(h3,al,2,hi,192);if(strcmp(h1,h2)||!strcmp(h1,h3))return 6;mpfr_clear(al[0]);mpfr_clear(al[1]);sda_candidate_set s;sda_candidate_set_init(&s,192);mpfr_set_d(a,.2,MPFR_RNDN);mpfr_set_d(b,.3,MPFR_RNDN);mpfr_set_d(c,1.1,MPFR_RNDN);size_t id;if(sda_candidate_set_observe(&s,3,3,p,cc,1,0,0,lo,1,a,b,c,0,"1234567890abcdef",&id)<0)return 6;mpfr_set_d(x,.2,MPFR_RNDN);sda_candidate_set_observe(&s,3,3,p,cc,2,0,1,x,1,a,b,c,0,"1234567890abcdef",&id);sda_candidate_set_observe(&s,3,3,qv,cc,3,1,0,x,0,a,b,c,0,"fedcba0987654321",&id);mpfr_set_d(x,.3,MPFR_RNDN);sda_candidate_set_observe(&s,3,3,p,cc,4,1,1,x,0,a,b,c,0,"1234567890abcdef",&id);if(s.count!=2||s.items[0].occurrences!=3||s.items[0].contiguous_run_count!=2||mpfr_cmp(s.items[0].epsilon_min,lo)||mpfr_cmp(s.items[0].epsilon_max,x))return 7;sda_candidate_set_clear(&s);mpfr_clears(lo,hi,x,last,pl,pu,slo,shi,a,b,c,(mpfr_ptr)0);return 0;}
